<template><view class="page"><view class="row"><view class="title task-title">{{date}} · 学习任务</view><text class="link" @click="record">学习记录 ›</text></view><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载…</view><EmptyState v-else-if="!plan"/>
<template v-else><view class="card summary"><view class="muted">{{plan.examName}}</view><view class="row"><view><text class="big">{{done}}</text><text class="muted"> / {{tasks.length}} 项已完成</text></view><text class="badge">{{minutes}} 分钟</text></view><view class="progress"><view class="fill" :style="{width:(tasks.length?done*100/tasks.length:0)+'%'}"/></view></view><view class="card row"><text class="link" @click="move(-1)">‹ 前一天</text><picker mode="date" :value="date" :start="plan.startDate" :end="endDate" @change="setDate"><text>{{date===today()?'今天 · ':''}}{{date}} ⌄</text></picker><text class="link" @click="move(1)">后一天 ›</text></view>
<view class="motivation"><view><view>今日也要加油喵！</view><text>追梦的每一天，离上岸更近一步</text></view><image src="/static/dengkemiao.png" mode="aspectFit"/></view><view class="task-tabs"><text :class="filter==='all'?'active':''" @click="filter='all'">今日任务 ({{tasks.length}})</text><text :class="filter==='done'?'active':''" @click="filter='done'">已完成 ({{done}})</text><text :class="filter==='pending'?'active':''" @click="filter='pending'">未完成</text></view>
<view v-if="!visibleTasks.length" class="card empty"><view class="title">{{tasks.length?'暂无符合条件的任务':plan.remainingDays===0?'祝你考试顺利！':'这一天没有任务'}}</view><view class="muted">{{tasks.length?'切换任务筛选查看其他安排。':'切换日期，查看备考期内的学习安排。'}}</view></view><view v-for="t in visibleTasks" :key="t.id" :class="['card','task',t.completed?'finished':'']"><view class="row"><view class="subject">{{t.subject}} · {{t.name}}</view><text class="muted duration">{{t.duration}}分钟</text></view><view class="row task-bottom"><text class="muted">{{t.completed?'又向目标靠近一步':'按自己的教材安排具体内容'}}</text><button :class="t.completed?'secondary':'primary'" :disabled="busy===t.id" @click="toggle(t)">{{t.completed?'✓ 已完成':'完成打卡'}}</button></view></view><view class="muted footer">学习时长按已完成任务的计划时长统计。</view></template></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,current,showError} from '../../api';import {today,addDays} from '../../utils/planner.mjs';import EmptyState from '../../components/EmptyState.vue'
const plan=ref(null),tasks=ref([]),date=ref(today()),loading=ref(true),error=ref(''),busy=ref(''),filter=ref('all');const visibleTasks=computed(()=>tasks.value.filter(t=>filter.value==='all'||(filter.value==='done'?t.completed:!t.completed)));const done=computed(()=>tasks.value.filter(t=>t.completed).length),minutes=computed(()=>tasks.value.reduce((a,t)=>a+t.duration,0)),endDate=computed(()=>plan.value?addDays(plan.value.examDate,-1):today())
async function load(){loading.value=true;error.value='';try{plan.value=await current();tasks.value=plan.value?await api.tasks(plan.value.id,date.value):[]}catch(e){error.value=e.message}finally{loading.value=false}}
async function toggle(t){if(busy.value)return;busy.value=t.id;try{await api.complete(t.id,!t.completed);t.completed=!t.completed}catch(e){showError(e)}finally{busy.value=''}}
function move(n){const next=addDays(date.value,n);if(next<plan.value.startDate||next>endDate.value)return;date.value=next;load()}function setDate(e){date.value=e.detail.value;load()}function record(){uni.navigateTo({url:'/pages/record/index'})}onShow(load)
</script>
<style scoped>.summary{margin-top:30rpx}.subject{font-size:30rpx;font-weight:750;color:#1677FF}.name{font-size:30rpx;font-weight:650;margin:20rpx 0 28rpx}.task button{padding:12rpx 22rpx;font-size:24rpx;white-space:nowrap}.finished{border:2rpx solid #BCE9D3;background:#FAFFFC}.finished .subject{color:#20A968}.footer{text-align:center;margin-top:28rpx}</style>
<style scoped>.task-title{font-size:27rpx}.motivation{display:flex;align-items:center;justify-content:space-between;background:linear-gradient(125deg,#93D4FF,#DCF4FF);border-radius:22rpx;padding:12rpx 24rpx;color:#0766CF;margin-bottom:20rpx;overflow:hidden}.motivation view view{font-size:33rpx;font-weight:800}.motivation text{font-size:21rpx;color:#426F91}.motivation image{width:165rpx;height:150rpx;margin-bottom:-15rpx}.task-tabs{display:flex;justify-content:space-between;color:#8190A8;font-size:25rpx;margin:24rpx 0}.task-tabs text{padding-bottom:15rpx;border-bottom:4rpx solid transparent}.task-tabs .active{color:#1677FF;border-color:#1677FF;font-weight:650}.task{padding:24rpx;border-radius:20rpx}.subject{font-size:25rpx;color:#172B4D}.duration{white-space:nowrap;font-size:22rpx}.task-bottom{margin-top:20rpx}.task-bottom .muted{font-size:21rpx}.task button{padding:8rpx 15rpx;font-size:21rpx}.summary{margin-top:20rpx}.summary .big{font-size:50rpx}</style>
